10. Instruction: Given a list of words, return the longest word in the list. 
10. Input:
['hello', 'world', 'this', 'is', 'a', 'test']
10. Output:
'world'
function longestWord(words) {
  let longest = '';
  for (let word of words) {
    if (word.length > longest.length) {
      longest = word;
    }
  }
  return longest;
}
longestWord(['hello', 'world', 'this', 'is', 'a', 'test']); // returns 'world

