10. Instruction: Write a JavaScript function to calculate the factorial of a given number.
10. Input: 5
10. Output: 120 
// JavaScript code to calculate factorial
function factorial(n) {
  if (n === 0 || n === 1) {
    return 1;
  } else {
    return n * factorial(n-1);
  }
}
console.log(factorial(5)); // Output: 120

